"""Prepare the approved runic polyhedron's independent animation and native playback pipeline."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];TOOLS=ROOT/'tools/art_pipeline'
STEM='veil_archon_blocky_v9_animated';ASSET=ROOT/'assets/generated/grand_manifestations'/STEM
def read(n):return (TOOLS/n).read_text(encoding='utf-8')
def write(n,s):(TOOLS/n).write_text(s,encoding='utf-8')
def names(s):
 return s.replace('nature_avatar_blocky_v5_animated',STEM).replace('Nature_Avatar_Blocky_V5_Animated','Veil_Archon_Blocky_V9_Animated').replace('NatureAvatarAnimationReview','VeilArchonAnimationReview').replace('NATURE_AVATAR_ANIMATION_VALIDATION','VEIL_ARCHON_ANIMATION_VALIDATION').replace('nature_avatar_animation_import','veil_archon_animation_import').replace('verify_nature_avatar_animations','verify_veil_archon_animations').replace('nature_avatar_animations_','veil_archon_animations_').replace('Nature Avatar Animation Review','Veil Archon Animation Review').replace('animated nature avatar','animated veil archon')
src=names(read('animate_nature_avatar_v5_mcp.py').split('# Floating locomotion')[0])
src=src.replace("['nature_avatar_blocky_v4']","['veil_archon_blocky_v8']").replace('Ancient_Roots_Green_Core','Runic_Plates_White_Violet_Core')
src=src.replace('for original in old[\'parts\']:\n    o=',"for original in old['parts']:\n    if original['kind']=='orbit':continue\n    o=")
src=src.replace('old_scenes=list(bpy.data.scenes.keys())',"for image in old['images']:\n    path=Path(image.filepath_raw);protected[str(path.relative_to(ROOT))]=hashlib.sha256(path.read_bytes()).hexdigest()\nold_scenes=list(bpy.data.scenes.keys())")
write('animate_veil_archon_v9_mcp.py',src+read('veil_archon_animation_motion.py'))
src=read('export_nature_avatar_v5_mcp.py')
head=names(src[:src.index('# Sample every half frame')])
head=head.replace("assert len(parts)==len(old['parts'])==86","approved=[o for o in old['parts'] if o['kind']!='orbit']\nassert len(parts)==len(approved)==47\nassert not any(o['kind']=='orbit' for o in parts) and 'orbit' not in rig.data.bones")
head=head.replace("zip(parts,old['parts'])","zip(parts,approved)")
tail=names(src[src.index('# Export a temporary assembled mesh'):])
tail=tail.replace("source_model='nature_avatar_blocky_v4'","source_model='veil_archon_blocky_v8'")
tail=tail.replace('suspended_root_geometry_preserved=True','retained_plates_lattice_and_core_preserved=True,external_purple_trails_removed=6')
tail=tail.replace('rest_crown_height_above_ground_m=3.,rest_height_m=2.5801127851','impact_time_s=.875,cast_time_s=2.,retained_parts=47')
write('export_veil_archon_v9_mcp.py',head+read('veil_archon_animation_audit.py')+'\n'+tail)
write('validate_veil_archon_animations.py',names(read('validate_nature_avatar_animations.py')))
verify=names(read('verify_nature_avatar_animations.gd')).replace('Avatar animation validation','Veil Archon animation validation').replace('create_timer(60)','create_timer(150)')
verify=verify.replace('"Idle":3.0,"Walk":1.0,"Attack":0.875,"Spell":1.75','"Idle":3.0,"Walk":1.0,"Attack":0.875,"Spell":2.0').replace('1.75 if clip=="Spell"','2.0 if clip=="Spell"')
verify=verify.replace('Interrupted spell must reset every arm, core and suspended root transform.','Interrupted spell must reset every plate, shell and core transform.')
write('verify_veil_archon_animations.gd',verify)
review=names((ROOT/'scripts/art_review/NatureAvatarAnimationReview.gd').read_text(encoding='utf-8')).replace('AVATAR DA NATUREZA','ARCONTE DO VÉU').replace('camera.size = 4.4','camera.size = 5.1').replace('Vector3(0, 1.8, 0)','Vector3(0, 2.0, 0)')
(ROOT/'scripts/art_review/VeilArchonAnimationReview.gd').write_text(review,encoding='utf-8')
(ROOT/'scenes/art_review/VeilArchonAnimationReview.tscn').write_text(names((ROOT/'scenes/art_review/NatureAvatarAnimationReview.tscn').read_text(encoding='utf-8')),encoding='utf-8')
ASSET.mkdir(parents=True,exist_ok=True)
(ASSET/'veil_archon_animation_import.gd').write_text((ROOT/'assets/generated/grand_manifestations/nature_avatar_blocky_v5_animated/nature_avatar_animation_import.gd').read_text(encoding='utf-8'),encoding='utf-8')
write('finalize_veil_archon_animations_mcp.py',names(read('finalize_nature_avatar_animations_mcp.py')))
print('Runic polyhedron animator, exporter, native validator and review prepared.')
